//go:build amd64

package per

import (
	"github.com/thebagchi/asn1c-go/lib/cpu"
)

// How many bytes each range kernel checks per iteration. RANGE_KERNEL_MIN is the
// shortest text _OutsideRange hands to the kernels: one AVX2 block. A shorter text stays
// on the word check, which costs less than a call.
const (
	RANGE_SSE2_BYTES   = 16
	RANGE_AVX2_BYTES   = 32
	RANGE_AVX512_BYTES = 64
	RANGE_KERNEL_MIN   = RANGE_AVX2_BYTES
)

// The kernels are generated by avo from gen/range.go into range_amd64.s. go vet's asmdecl
// check holds the declarations below and the assembly's frames in step. Regenerate with
// "make generate" after editing anything under gen/.
//
//go:generate go run ./gen -only range -out range_amd64.s -pkg per

// _CheckRangeKernels checks text against lower..upper with the assembly kernels, widest
// first, and returns how many leading bytes are inside: whole blocks, up to the first
// block with a byte outside. The caller checks the rest, so it reports the error.
//
// The kernels are called by name, for the reason _PackNumeric gives. AVX2 takes the
// half block that AVX-512 leaves and SSE2 the half block that AVX2 leaves; the AVX-512
// and AVX2 kernels end in VZEROUPPER.
//
// Revisions:
//   - 2026-10-21 16:08: initial creation (review P28)
//   - 2026-10-21 23:53: the AVX-512 kernel first, when cpu.HAS_AVX512 (review P33)
func _CheckRangeKernels(
	text []byte,
	lower,
	upper byte,
) int {
	var (
		done int
	)

	if cpu.HAS_AVX512 {
		done = _CheckRangeAVX512(
			text,
			lower,
			upper,
		)
	}

	if rest := text[done:]; cpu.HAS_AVX2 && len(rest) >= RANGE_AVX2_BYTES {
		done += _CheckRangeAVX2(
			rest,
			lower,
			upper,
		)
	}

	if rest := text[done:]; len(rest) >= RANGE_SSE2_BYTES {
		done += _CheckRangeSSE2(
			rest,
			lower,
			upper,
		)
	}

	return done
}

// _CheckRangeSSE2 checks that each byte of src is in lower..upper, sixteen bytes per
// iteration, and returns how many bytes it checked: a multiple of sixteen, short of
// len(src) when a block holds a byte outside the range. It is declared noescape so a
// caller's slice stays where it is.
//
// Revisions:
//   - 2026-10-21 16:08: initial creation (review P28)
//
//go:noescape
func _CheckRangeSSE2(
	src []byte,
	lower,
	upper byte,
) int

// _CheckRangeAVX2 is _CheckRangeSSE2 at thirty-two bytes per iteration.
//
// Revisions:
//   - 2026-10-21 16:08: initial creation (review P28)
//
//go:noescape
func _CheckRangeAVX2(
	src []byte,
	lower,
	upper byte,
) int

// _CheckRangeAVX512 is _CheckRangeSSE2 at sixty-four bytes per iteration, in EVEX
// encodings only, ending in VZEROUPPER. It needs AVX512BW.
//
// Revisions:
//   - 2026-10-21 23:53: initial creation (review P33)
//
//go:noescape
func _CheckRangeAVX512(
	src []byte,
	lower,
	upper byte,
) int
